content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --secondary-color: #f3f4f6;
  --secondary-hover: #e5e7eb;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --bg-color: #f9fafb;
  --card-bg: #ffffff;
  --border-color: #e5e7eb;
  --success-color: #10b981;
  --danger-color: #ef4444;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #6366f1;
    --primary-hover: #4f46e5;
    --secondary-color: #374151;
    --secondary-hover: #4b5563;
    --text-main: #f9fafb;
    --text-muted: #9ca3af;
    --bg-color: #111827;
    --card-bg: #1f2937;
    --border-color: #374151;
    --success-color: #34d399;
    --danger-color: #f87171;
    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -1px rgba(0, 0, 0, 0.18);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
}

.app-container {
  max-width: 900px;
  margin: 0 auto;
  padding: 20px;
}

.header {
  text-align: center;
  margin-bottom: 24px;
}

.header h1 {
  font-size: 2.2rem;
  color: var(--primary-color);
  margin-bottom: 8px;
}

.header p {
  color: var(--text-muted);
}

.stats-bar {
  background: var(--card-bg);
  padding: 16px 20px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  margin-bottom: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stats-info {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: bold;
}

.progress-bar {
  width: 100%;
  height: 12px;
  background-color: var(--secondary-color);
  border-radius: 6px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background-color: var(--success-color);
  transition: width 0.3s ease;
}

.filter-container {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 24px;
  justify-content: center;
}

.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 20px;
  margin-bottom: 32px;
}

.card-wrapper {
  perspective: 1000px;
  height: 220px;
  cursor: pointer;
}

.flash-card {
  width: 100%;
  height: 100%;
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.6s;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.card-face {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 20px;
  border-radius: var(--radius);
  background: var(--card-bg);
  border: 1px solid var(--border-color);
}

.card-front {
  z-index: 2;
}

.card-back {
  transform: rotateY(180deg);
  background-color: var(--card-bg);
  border-color: var(--border-color);
  justify-content: center;
  align-items: center;
  text-align: center;
}

.card-category {
  font-size: 0.75rem;
  background: var(--secondary-color);
  padding: 2px 8px;
  border-radius: 4px;
  align-self: flex-start;
  color: var(--text-muted);
}

.card-content {
  text-align: center;
  margin: auto 0;
}

.card-content h3 {
  font-size: 1.5rem;
  color: var(--text-main);
  margin-bottom: 4px;
}

.card-content p {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.card-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: auto;
}

.btn {
  padding: 8px 16px;
  border-radius: 6px;
  border: none;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.96);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  background-color: var(--secondary-color);
  color: var(--text-main);
}

.btn-secondary:hover {
  background-color: var(--secondary-hover);
}

.btn-danger {
  background-color: #fee2e2;
  color: var(--danger-color);
}

@media (prefers-color-scheme: dark) {
  .btn-danger {
    background-color: rgba(239, 68, 68, 0.2);
  }
}

.btn-danger:hover {
  background-color: #fecaca;
}

.btn-success {
  background-color: #d1fae5;
  color: var(--success-color);
}

@media (prefers-color-scheme: dark) {
  .btn-success {
    background-color: rgba(16, 185, 129, 0.2);
  }
}

.btn-success:hover {
  background-color: #a7f3d0;
}

.form-container {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  margin-bottom: 32px;
}

.form-container h3 {
  margin-bottom: 16px;
  color: var(--text-main);
}

.form-group {
  margin-bottom: 16px;
}

.form-group label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 6px;
  color: var(--text-main);
}

.form-group input,
.form-group select {
  width: 100%;
  padding: 10px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  font-size: 1rem;
  background-color: var(--card-bg);
  color: var(--text-main);
}

.form-group input:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--primary-color);
}

@media (max-width: 600px) {
  body {
    padding: 10px;
  }
  .app-container {
    padding: 10px;
  }
  .cards-grid {
    grid-template-columns: 1fr;
  }
}

export type CategoryType = '日常' | '動物' | '果物' | '自然' | '人間' | 'その他' | (string & {});

export interface WordCard {
  id: string;
  english: string;
  japanese: string;
  example: string;
  category: CategoryType;
  remembered: boolean;
  reviewCount?: number;
  lastReviewedAt?: string;
}

export interface WordCardProps {
  card: WordCard;
  onToggleRemember: (id: string) => void;
  onDelete: (id: string) => void;
}

import { useState } from 'react';
import { WordCardProps } from '../types';

export default function WordCard({ card, onToggleRemember, onDelete }: WordCardProps) {
  const [isFlipped, setIsFlipped] = useState(false);

  const handleCardClick = (e: React.MouseEvent) => {
    if ((e.target as HTMLElement).closest('button')) return;
    setIsFlipped(!isFlipped);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if ((e.target as HTMLElement).closest('button')) return;
      setIsFlipped(!isFlipped);
    }
  };

  return (
    <div
      className="card-wrapper"
      onClick={handleCardClick}
      onKeyDown={handleKeyDown}
      tabIndex={0}
      role="button"
      aria-pressed={isFlipped}
      aria-label={`単語カード: ${card.english}`}
    >
      <div
        className="flash-card"
        style={{ transform: isFlipped ? 'rotateY(180deg)' : 'rotateY(0deg)' }}
      >
        <div className="card-face card-front">
          <span className="card-category">{card.category}</span>
          <div className="card-content">
            <h3>{card.english}</h3>
            <p>{card.example}</p>
          </div>
          <div className="card-actions">
            <button
              type="button"
              className={`btn ${card.remembered ? 'btn-success' : 'btn-secondary'}`}
              onClick={(e) => {
                e.stopPropagation();
                onToggleRemember(card.id);
              }}
            >
              {card.remembered ? '覚えた！' : '未習得'}
            </button>
            <button
              type="button"
              className="btn btn-danger"
              onClick={(e) => {
                e.stopPropagation();
                onDelete(card.id);
              }}
            >
              削除
            </button>
          </div>
        </div>
        <div className="card-face card-back">
          <div className="card-content">
            <h3>{card.japanese}</h3>
            <p>クリックして戻る</p>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { WordCard as WordCardType } from './types';
import WordCard from './components/WordCard';

const INITIAL_WORDS: WordCardType[] = [
  { id: '1', english: 'Apple', japanese: 'リンゴ', example: 'I ate a red apple.', category: '果物', remembered: false },
  { id: '2', english: 'Book', japanese: '本', example: 'She is reading an interesting book.', category: '日常', remembered: false },
  { id: '3', english: 'Cat', japanese: '猫', example: 'The cat is sleeping on the sofa.', category: '動物', remembered: false },
  { id: '4', english: 'Dog', japanese: '犬', example: 'My dog loves to run in the park.', category: '動物', remembered: false },
  { id: '5', english: 'Elephant', japanese: '象', example: 'An elephant has a long trunk.', category: '動物', remembered: false },
  { id: '6', english: 'Friend', japanese: '友達', example: 'He is my best friend.', category: '人間', remembered: false },
  { id: '7', english: 'Garden', japanese: '庭', example: 'We grow flowers in the garden.', category: '自然', remembered: false },
  { id: '8', english: 'House', japanese: '家', example: 'They live in a big house.', category: '日常', remembered: false },
  { id: '9', english: 'Island', japanese: '島', example: 'Hawaii is a beautiful island.', category: '自然', remembered: false },
  { id: '10', english: 'Journey', japanese: '旅', example: 'Life is a long journey.', category: '日常', remembered: false },
];

const LOCAL_STORAGE_KEY = 'flash_card_words_v1';

export default function App() {
  const [words, setWords] = useState<WordCardType[]>(() => {
    const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error('Failed to load words from localStorage', e);
      }
    }
    return INITIAL_WORDS;
  });

  useEffect(() => {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(words));
  }, [words]);

  const [filterCategory, setFilterCategory] = useState<string>('すべて');
  const [filterStatus, setFilterStatus] = useState<string>('すべて');

  const [english, setEnglish] = useState('');
  const [japanese, setJapanese] = useState('');
  const [example, setExample] = useState('');
  const [category, setCategory] = useState('日常');
  const [errorMessage, setErrorMessage] = useState('');

  const categories = ['すべて', ...Array.from(new Set(words.map(w => w.category)))];

  const handleToggleRemember = (id: string) => {
    setWords(words.map(w => w.id === id ? { ...w, remembered: !w.remembered } : w));
  };

  const handleDelete = (id: string) => {
    setWords(words.filter(w => w.id !== id));
  };

  const handleReset = () => {
    setWords(words.map(w => ({ ...w, remembered: false })));
  };

  const handleAddWord = (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMessage('');

    const trimmedEnglish = english.trim();
    const trimmedJapanese = japanese.trim();
    const trimmedExample = example.trim();

    if (!trimmedEnglish || !trimmedJapanese) {
      setErrorMessage('英語と日本語訳は必須です。');
      return;
    }

    if (trimmedEnglish.length > 50) {
      setErrorMessage('英語は50文字以内で入力してください。');
      return;
    }

    if (trimmedJapanese.length > 50) {
      setErrorMessage('日本語訳は50文字以内で入力してください。');
      return;
    }

    if (trimmedExample.length > 150) {
      setErrorMessage('例文は150文字以内で入力してください。');
      return;
    }

    const newCard: WordCardType = {
      id: Date.now().toString(),
      english: trimmedEnglish,
      japanese: trimmedJapanese,
      example: trimmedExample || '例文なし',
      category: category.trim() || '日常',
      remembered: false,
    };

    setWords([newCard, ...words]);
    setEnglish('');
    setJapanese('');
    setExample('');
    setErrorMessage('');
  };

  const filteredWords = words.filter(w => {
    const matchCategory = filterCategory === 'すべて' || w.category === filterCategory;
    const matchStatus = 
      filterStatus === 'すべて' ? true :
      filterStatus === '覚えた' ? w.remembered : !w.remembered;
    return matchCategory && matchStatus;
  });

  const rememberedCount = words.filter(w => w.remembered).length;
  const totalCount = words.length;
  const progressPercent = totalCount > 0 ? Math.round((rememberedCount / totalCount) * 100) : 0;

  return (
    <div className="app-container">
      <header className="header">
        <h1>英単語暗記カード</h1>
        <p>カードをクリックして裏返し、単語を楽しく覚えましょう！</p>
      </header>

      <section className="stats-bar">
        <div className="stats-info">
          <span>進捗: {rememberedCount} / {totalCount} 語 ({progressPercent}%)</span>
          <button type="button" className="btn btn-secondary" onClick={handleReset}>
            やり直す
          </button>
        </div>
        <div className="progress-bar">
          <div className="progress-fill" style={{ width: `${progressPercent}%` }} />
        </div>
      </section>

      <div className="filter-container">
        {categories.map(cat => (
          <button
            key={cat}
            type="button"
            className={`btn ${filterCategory === cat ? 'btn-primary' : 'btn-secondary'}`}
            onClick={() => setFilterCategory(cat)}
          >
            {cat}
          </button>
        ))}
        <button
          type="button"
          className={`btn ${filterStatus === 'すべて' ? 'btn-primary' : 'btn-secondary'}`}
          onClick={() => setFilterStatus('すべて')}
        >
          すべて表示
        </button>
        <button
          type="button"
          className={`btn ${filterStatus === '未習得' ? 'btn-primary' : 'btn-secondary'}`}
          onClick={() => setFilterStatus('未習得')}
        >
          未習得のみ
        </button>
        <button
          type="button"
          className={`btn ${filterStatus === '覚えた' ? 'btn-primary' : 'btn-secondary'}`}
          onClick={() => setFilterStatus('覚えた')}
        >
          覚えたのみ
        </button>
      </div>

      <div className="cards-grid">
        {filteredWords.map(card => (
          <WordCard
            key={card.id}
            card={card}
            onToggleRemember={handleToggleRemember}
            onDelete={handleDelete}
          />
        ))}
        {filteredWords.length === 0 && (
          <p style={{ textAlign: 'center', gridColumn: '1 / -1', color: 'var(--text-muted)' }}>
            該当する単語がありません。
          </p>
        )}
      </div>

      <section className="form-container">
        <h3>新しい単語を追加</h3>
        {errorMessage && (
          <p style={{ color: 'var(--danger-color)', marginBottom: '12px', fontSize: '0.9rem', fontWeight: 'bold' }}>
            {errorMessage}
          </p>
        )}
        <form onSubmit={handleAddWord}>
          <div className="form-group">
            <label>英語 (English)</label>
            <input
              type="text"
              value={english}
              onChange={e => setEnglish(e.target.value)}
              placeholder="例: Apple"
              maxLength={50}
              required
            />
          </div>
          <div className="form-group">
            <label>日本語訳 (Japanese)</label>
            <input
              type="text"
              value={japanese}
              onChange={e => setJapanese(e.target.value)}
              placeholder="例: リンゴ"
              maxLength={50}
              required
            />
          </div>
          <div className="form-group">
            <label>例文 (Example)</label>
            <input
              type="text"
              value={example}
              onChange={e => setExample(e.target.value)}
              placeholder="例: I ate a red apple."
              maxLength={150}
            />
          </div>
          <div className="form-group">
            <label>カテゴリ</label>
            <select value={category} onChange={e => setCategory(e.target.value)}>
              <option value="日常">日常</option>
              <option value="動物">動物</option>
              <option value="果物">果物</option>
              <option value="自然">自然</option>
              <option value="人間">人間</option>
              <option value="その他">その他</option>
            </select>
          </div>
          <button type="submit" className="btn btn-primary">単語を追加する</button>
        </form>
      </section>
    </div>
  );
}
